package mz.bam.seeky.android;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.function.BooleanSupplier;import java.util.zip.*;
import org.apache.commons.compress.archivers.*;import org.apache.commons.compress.archivers.zip.*;import org.apache.commons.compress.archivers.tar.*;import org.apache.commons.compress.archivers.sevenz.*;import org.apache.commons.compress.compressors.*;
/** Streaming archives, private staging and publication only after a complete operation. */
final class ArchiveFiles {
 static final long MAX_BYTES=16L*1024*1024*1024;static final int MAX_ENTRIES=50000;
 interface Progress{void update(String name,long bytes,int entries);}
 static final class Work {final BooleanSupplier cancel;final Progress progress;long bytes,last;int entries;Work(BooleanSupplier c,Progress p){cancel=c;progress=p;}void check()throws IOException{if(cancel.getAsBoolean()||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Operação cancelada.");}void entry(String n)throws IOException{check();if(++entries>MAX_ENTRIES)throw new IOException("Arquivo acima de 50 mil entradas.");notify(n);}void notify(String n){long now=System.currentTimeMillis();if(now-last>=150){last=now;progress.update(n,bytes,entries);}}void copy(InputStream in,OutputStream out,String n)throws IOException{byte[] b=new byte[65536];for(int size;(size=in.read(b))!=-1;){check();if(size==0)continue;bytes+=size;if(bytes>MAX_BYTES)throw new IOException("Operação acima do limite de 16 GB.");out.write(b,0,size);notify(n);}}}
 static boolean accepts(String name){String n=name.toLowerCase(Locale.ROOT);return n.matches(".*\\.(zip|rar|7z|tar|tgz|gz|bz2|tbz2|xz|txz)$");}
 static File child(File root,String name)throws IOException{String n=name.replace('\\','/');if(n.length()>4096||n.split("/").length>64)throw new IOException("Caminho demasiado longo no arquivo.");if(n.isEmpty()||n.indexOf('\0')>=0||n.startsWith("/")||n.matches("^[A-Za-z]:.*"))throw new IOException("Caminho inválido no arquivo.");for(String part:n.split("/"))if(part.equals(".."))throw new IOException("Caminho fora da pasta de destino.");File f=new File(root,n).getCanonicalFile();if(!f.getPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("Caminho fora da pasta de destino.");return f;}
 static void remove(File file){if(file.isDirectory()){File[] files=file.listFiles();if(files!=null)for(File f:files)remove(f);}file.delete();}
 static File reserve(File folder,String name)throws IOException{if(!folder.isDirectory())throw new IOException("A pasta de destino não existe.");File f=child(folder,name);if(f.exists())throw new IOException("Já existe um ficheiro ou pasta com este nome. Escolha outro nome.");return f;}
 static void writeEntry(File stage,ArchiveEntry e,InputStream input,Work w)throws IOException{w.entry(e.getName());if(e instanceof TarArchiveEntry&&(((TarArchiveEntry)e).isSymbolicLink()||((TarArchiveEntry)e).isLink()||((TarArchiveEntry)e).isFIFO()||((TarArchiveEntry)e).isBlockDevice()||((TarArchiveEntry)e).isCharacterDevice()||!((TarArchiveEntry)e).isFile()&&!e.isDirectory()))throw new IOException("O arquivo contém ligações ou entradas especiais.");if(e instanceof ZipArchiveEntry&&((ZipArchiveEntry)e).isUnixSymlink())throw new IOException("O arquivo contém uma ligação simbólica.");if(e.getSize()>MAX_BYTES-w.bytes)throw new IOException("Conteúdo acima de 16 GB.");File out=child(stage,e.getName());if(e.isDirectory()){if(!out.isDirectory()&&!out.mkdirs())throw new IOException("Não foi possível criar a pasta.");return;}if(out.exists())throw new IOException("Entrada repetida no arquivo: "+e.getName());if(!out.getParentFile().isDirectory()&&!out.getParentFile().mkdirs())throw new IOException("Não foi possível criar a pasta.");try(OutputStream target=new BufferedOutputStream(new FileOutputStream(out))){w.copy(input,target,e.getName());}if(e.getSize()>=0&&out.length()!=e.getSize())throw new IOException("Entrada incompleta: "+e.getName());}
 static File extract(File source,File folder,String name,char[] password,BooleanSupplier cancelled,Progress progress)throws Exception{File target=reserve(folder,name),stage=new File(folder,".seeky-extract-"+UUID.randomUUID());if(!stage.mkdir())throw new IOException("Não foi possível preparar a extracção.");Work w=new Work(cancelled,progress);boolean published=false;
  try{String lower=source.getName().toLowerCase(Locale.ROOT);if(lower.endsWith(".rar"))throw new IOException("A extracção RAR ainda requer um motor adicional. Use Abrir com para uma aplicação compatível; ZIP, 7z e TAR têm extracção integrada.");
   if(lower.endsWith(".7z")){try(SevenZFile seven=new SevenZFile(source,password,SevenZFileOptions.builder().withMaxMemoryLimitInKb(32768).build())){SevenZArchiveEntry e;while((e=seven.getNextEntry())!=null){if(e.getHasWindowsAttributes()&&((e.getWindowsAttributes()&0x400)!=0||((e.getWindowsAttributes()>>>16)&0xf000)==0xa000))throw new IOException("O arquivo contém uma ligação especial.");InputStream in=new InputStream(){public int read()throws IOException{return seven.read();}public int read(byte[] b,int off,int len)throws IOException{return seven.read(b,off,len);}};writeEntry(stage,e,in,w);}}}
   else{try(BufferedInputStream raw=new BufferedInputStream(new FileInputStream(source))){raw.mark(16);byte[] magic=new byte[8];int read=raw.read(magic);raw.reset();boolean zip=read>=4&&magic[0]=='P'&&magic[1]=='K';if(zip){try(ZipArchiveInputStream in=new ZipArchiveInputStream(raw,"UTF-8",true,true)){ZipArchiveEntry e,previous=null;long previousCrc=0;while((e=in.getNextZipEntry())!=null){if(previous!=null&&previous.getCrc()>=0&&previousCrc!=previous.getCrc())throw new IOException("Verificação CRC falhou: "+previous.getName());if(!in.canReadEntryData(e))throw new IOException("ZIP cifrado ou método de compressão não suportado.");CheckedInputStream checked=new CheckedInputStream(in,new CRC32());writeEntry(stage,e,checked,w);previous=e;previousCrc=checked.getChecksum().getValue();if(e.getCrc()>=0&&checked.getChecksum().getValue()!=e.getCrc())throw new IOException("Verificação CRC falhou: "+e.getName());}if(previous!=null&&previous.getCrc()>=0&&previousCrc!=previous.getCrc())throw new IOException("Verificação CRC falhou: "+previous.getName());if(w.entries==0&&(magic[2]!=5||magic[3]!=6))throw new IOException("ZIP vazio ou danificado.");}}else{InputStream content=raw;boolean compressed=lower.endsWith(".gz")||lower.endsWith(".tgz")||lower.endsWith(".bz2")||lower.endsWith(".tbz2")||lower.endsWith(".xz")||lower.endsWith(".txz");if(compressed)content=new CompressorStreamFactory(true,32768).createCompressorInputStream(new BufferedInputStream(raw));boolean tar=lower.endsWith(".tar")||lower.matches(".*\\.(tgz|tbz2|txz)$")||lower.matches(".*\\.tar\\.(gz|bz2|xz)$");try(InputStream decoded=content){if(tar){TarArchiveInputStream in=new TarArchiveInputStream(decoded);TarArchiveEntry e;while((e=in.getNextTarEntry())!=null)writeEntry(stage,e,in,w);}else{String base=source.getName().replaceFirst("(?i)\\.(gz|bz2|xz)$","");if(!compressed)throw new IOException("Formato de arquivo não suportado.");w.entry(base);File out=child(stage,base);try(OutputStream sink=new BufferedOutputStream(new FileOutputStream(out))){w.copy(decoded,sink,base);}}}}}}
   w.check();if(target.exists()||!stage.renameTo(target))throw new IOException("Não foi possível concluir a extracção. O destino anterior foi conservado.");published=true;progress.update(target.getName(),w.bytes,w.entries);return target;
  }finally{if(password!=null)Arrays.fill(password,'\0');if(!published)remove(stage);}
 }
 static File compress(List<File> sources,File folder,String name,BooleanSupplier cancelled,Progress progress)throws Exception{File target=reserve(folder,name),stage=new File(folder,".seeky-zip-"+UUID.randomUUID());Work w=new Work(cancelled,progress);Set<String> roots=new HashSet<>();for(File f:sources){if(!roots.add(f.getName()))throw new IOException("Existem origens com o mesmo nome. Renomeie-as antes de compactar.");if(f.isDirectory()&&target.getCanonicalPath().startsWith(f.getCanonicalPath()+File.separator))throw new IOException("Escolha um destino fora das pastas que vai compactar.");}if(sources.isEmpty())throw new IOException("Seleccione ficheiros para compactar.");boolean published=false;try{try(ZipArchiveOutputStream out=new ZipArchiveOutputStream(stage)){out.setUseZip64(Zip64Mode.AsNeeded);out.setEncoding("UTF-8");out.setUseLanguageEncodingFlag(true);for(File f:sources)add(out,f,f.getName(),w);}w.check();if(target.exists()||!stage.renameTo(target))throw new IOException("Não foi possível publicar o ZIP; o destino anterior foi conservado.");published=true;progress.update(target.getName(),w.bytes,w.entries);return target;}finally{if(!published)remove(stage);}}
 static void add(ZipArchiveOutputStream out,File f,String name,Work w)throws IOException{w.check();if(Files.isSymbolicLink(f.toPath()))throw new IOException("Não é possível compactar ligações simbólicas.");if(!f.exists())throw new IOException("Origem indisponível: "+name);w.entry(name);ZipArchiveEntry entry=new ZipArchiveEntry(name+(f.isDirectory()?"/":""));entry.setTime(f.lastModified());out.putArchiveEntry(entry);if(f.isDirectory()){out.closeArchiveEntry();File[] children=f.listFiles();if(children==null)throw new IOException("Sem acesso à pasta "+name);Arrays.sort(children,Comparator.comparing(File::getName));for(File child:children)add(out,child,name+"/"+child.getName(),w);}else if(f.isFile()){try(InputStream in=new BufferedInputStream(new FileInputStream(f))){w.copy(in,out,name);}out.closeArchiveEntry();}else throw new IOException("Tipo de ficheiro não suportado.");}
 private ArchiveFiles(){}
}
